import{evaluateStoryExpression}from'./gates.mjs';
import{enhancedLeagueActive}from'./enhanced-league.mjs';
// Pure extraction of existing StoryProgressionService predicates; no mutations or caller approval callback.
const gate=(id,save,contract)=>{if(!contract.gates[id])throw Error('Unknown canonical gate');return evaluateStoryExpression(id,save,contract)};
export function storyStageUnlocked(id,save,contract){const st=contract.stages[id];return !!st&&st.prerequisites.every(p=>save.progress.completedStages.includes(p))&&(!st.entryGate||gate(st.entryGate,save,contract))}
export function storyEventReady(id,save,contract){const e=contract.events[id],p=save.progress;if(enhancedLeagueActive(save))return false;return !!e?.active&&!e.acquisitionOnly&&e.stageId===p.currentStage&&!p.completedEvents.includes(id)&&e.requiresEvents.every(x=>p.completedEvents.includes(x))&&e.requiresGates.every(x=>gate(x,save,contract))&&(id!=='FINAL_LEAGUE'||p.leagueWins.length===4)}
export function storyTrainerAvailable(id,save,contract){const t=contract.trainers[id],p=save.progress;if(enhancedLeagueActive(save)||!t||t.stageId!==p.currentStage||!save.party.some(m=>m.hp>0)||!storyStageUnlocked(t.stageId,save,contract)||p.defeatedTrainers.includes(id)&&!t.repeatable)return false;if(t.eventId&&!storyEventReady(t.eventId,save,contract))return false;if(t.kind==='gym'&&Object.values(contract.trainers).some(x=>x.stageId===t.stageId&&x.kind==='gym_subtrainer'&&x.required&&!p.defeatedTrainers.includes(x.id)))return false;if(t.kind==='elite'&&(p.flags.MAIN_STORY_CLEAR||p.leagueWins.length!==t.order-1||!gate('CAN_ENTER_LEAGUE',save,contract)))return false;return true}
